import numpy as np

# Hole mask from W1 ch0 row norms
norms = np.linalg.norm(W['W1'], axis=1).reshape(10, 10, 5)
hole = np.zeros((10, 10), dtype=bool)
for r in range(1, 9):
    for c in range(1, 9):
        hole[r, c] = norms[r, c, 0] < 1.0

print("Hole mask (ch0 norm < 1):")
for r in range(1, 9):
    print(''.join('#' if hole[r, c] else '.' for c in range(1, 9)))

# Batch all 64 playable agent positions, no previous frame, border obstacles set
X = np.zeros((64, 500), dtype=np.float32)
k = 0
for r in range(1, 9):
    for c in range(1, 9):
        # border channel 3
        for rr in range(10):
            for cc in range(10):
                if rr == 0 or rr == 9 or cc == 0 or cc == 9:
                    X[k, (rr * 10 + cc) * 5 + 3] = 1.0
        # agent channel 0
        X[k, (r * 10 + c) * 5 + 0] = 1.0
        k += 1

logits = forward(X)
argmax = np.argmax(logits, axis=1)
symbols = ['0', '^', 'v', '<', '>']

print("\nArgmax action map (agent only, no prev):")
for r in range(1, 9):
    row = []
    for c in range(1, 9):
        idx = (r - 1) * 8 + (c - 1)
        row.append(symbols[argmax[idx]])
    print(''.join(row))
